import Foundation
import Dispatch
import Matter

func testBaseRelativeHumidityMeasurementInit() {
    let controller = MTRDeviceController()
    let device = MTRDevice(nodeID: n(1), controller: controller)
    let baseDevice: MTRBaseDevice = device
    _ = (device, baseDevice)
    _ = MTRBaseClusterRelativeHumidityMeasurement(device: baseDevice, endpointID: n(1), queue: DispatchQueue.global())
    _ = MTRBaseClusterRelativeHumidityMeasurement(device: baseDevice, endpoint: 1, queue: DispatchQueue.global())
}

